insert into public.user_ach(user_id,code,label,bonus,by) select p.id,c.code,c.label,0,(select id from public.profiles where full_name='Игорь Шубчик') from public.profiles p join (values ('Кристина Прошутинская','spec:media','Единорог «Медиа»'),('Мария Ярошенко','spec:media','Единорог «Медиа»'),('Кристина Прошутинская','spec:skin_kristina','Неоновый бит'),('Мария Ярошенко','spec:skin_masha','Кофейный рассвет')) c(name,code,label) on p.full_name=c.name on conflict(user_id,code) do nothing;
insert into public.notifications(kind,title,body,link) select 'ach','🎰 Новая волна в автомате: 80 вещей','Космос, техника, еда и кофе: питомцам, рамкам, именам и фонам. А ещё у супервайзеров появился особый питомец, единорог «Медиа».','game' where not exists(select 1 from public.notifications where title like '🎰 Новая волна%');
